insert into public.events (external_id, title, category, tags, starts_at, ends_at, is_long, venue_id, address, price_min, price_max, is_free, about, organizer, source_url, confidence, status, visibility) values
  ('seed-001', 'Стендап-концерт «Новые шутки»', 'standup', array['стендап','юмор','бар']::text[], '2026-09-29T21:00:00+05:00', null, false, (select id from public.venues where name = 'Hoper''s bar'), 'проспект Гагарина, 93', 3500, 3500, false, 'Вечер нового материала от комиков Stand Up Camp в баре. Камерный формат, где многое держится на реакции зала.', 'Stand Up Camp', 'https://sxodim.com/almaty/events/standup', 'high', 'published', 'public'),
  ('seed-002', 'Стендап-шоу «Очень-очень много комиков»', 'standup', array['стендап','юмор','сборный концерт']::text[], '2026-09-30T21:00:00+05:00', null, false, (select id from public.venues where name = 'Pinta Bar&Grill'), 'улица Тулебаева, 38А', 2500, 2500, false, 'Сборный концерт: несколько комиков по очереди читают короткие сеты. Удобный формат, если идёшь на стендап впервые.', 'Stand Up Camp', 'https://sxodim.com/almaty/events/standup', 'high', 'published', 'public'),
  ('seed-003', 'English Standup: Best Jokes & Live Crowdwork', 'standup', array['стендап','на английском','бар']::text[], '2026-10-01T20:00:00+05:00', null, false, (select id from public.venues where name = 'Saz Eleven Bar (Rixos Almaty)'), 'проспект Сейфуллина, 506', 3500, null, false, 'Стендап на английском с общением с залом. Хороший вариант потренировать английский и посмеяться.', null, 'https://sxodim.com/almaty/events/standup', 'high', 'published', 'public'),
  ('seed-004', 'Спектакль «Наши жёны»', 'theatre', array['театр','комедия','спектакль']::text[], '2026-10-01T19:00:00+05:00', null, false, (select id from public.venues where name = 'Театр Concordia'), 'улица Богенбай батыра, 151', 10000, null, false, 'Французская комедия положений о семейных секретах и неловких совпадениях. Лёгкий вечерний спектакль вдвоём или компанией.', 'Театр Concordia', 'https://sxodim.com/almaty/afisha', 'high', 'published', 'public'),
  ('seed-005', 'Вечер живой музыки в «Құт»', 'music', array['живая музыка','ресторан','вечер']::text[], '2026-10-01T18:00:00+05:00', null, false, (select id from public.venues where name = 'Ресторан «Құт»'), 'улица Тургута Озала, 178', 5000, 5000, false, 'Живой звук за ужином в ресторане. Спокойный вечер с друзьями без большого концертного зала.', null, 'https://sxodim.com/almaty/afisha', 'high', 'published', 'public'),
  ('seed-006', 'Концерт группы «Дурной Вкус»', 'music', array['рок','концерт','клуб']::text[], '2026-10-02T19:00:00+05:00', null, false, (select id from public.venues where name = 'Клуб «Жесть»'), 'улица Розыбакиева, 236', 15000, null, false, 'Живая программа группы «Дурной Вкус» в клубе. Для тех, кто любит гитарные концерты в небольшом зале.', null, 'https://sxodim.com/almaty/afisha', 'high', 'published', 'public'),
  ('seed-007', 'Ярмарка ремесленников Ala Craft', 'art', array['ярмарка','ремёсла','хендмейд']::text[], '2026-10-02T10:00:00+05:00', '2026-10-04T19:00:00+05:00', true, (select id from public.venues where name = 'Центральный выставочный зал Музея искусств им. Кастеева'), 'улица Желтоксан, 137', null, null, false, 'Мастера из Центральной Азии привозят украшения, текстиль и керамику ручной работы. Повод найти необычный подарок и поговорить с теми, кто это делает.', null, 'https://standard.kz/ru/post/2026_09_vystavka-iarmarka-remeslennikov-centralnoi-azii-otkroetsia-v-almaty-489', 'high', 'published', 'public'),
  ('seed-008', 'Спектакль «Подыскиваю жену. Недорого!»', 'theatre', array['театр','комедия','спектакль']::text[], '2026-10-03T19:30:00+05:00', null, false, (select id from public.venues where name = 'Театр Concordia'), 'улица Богенбай батыра, 151', 11000, null, false, 'Комедия о поисках спутницы жизни с неожиданными поворотами. Чтобы посмеяться после рабочей недели.', 'Театр Concordia', 'https://sxodim.com/almaty/events/teatr', 'high', 'published', 'public'),
  ('seed-009', 'Ярмарка выходного дня: фермерские продукты', 'food', array['ярмарка','фермеры','бесплатно']::text[], '2026-10-03T09:00:00+05:00', '2026-10-03T17:00:00+05:00', true, (select id from public.venues where name = 'Ярмарка выходного дня'), 'угол улиц Гоголя и Масанчи', null, null, true, 'Фермеры из Алматы и области продают овощи, фрукты, мясо, молочное и мёд напрямую. Можно закупиться свежим и прогуляться по району.', 'Акимат Алматы', 'https://open-almaty.kz/zhiznennye-situatsii/zhitelyam/prochee/prochee/adresa-ezhenedelnykh-yarmarok-vykhodnogo-dnya-v-almaty', 'medium', 'published', 'public'),
  ('seed-010', 'Открытая беговая тренировка Open Run', 'sport', array['бег','тренировка','бесплатно']::text[], '2026-10-03T19:00:00+05:00', null, false, (select id from public.venues where name = 'Центральный стадион'), 'улица Сатпаева, 29/3', null, null, true, 'Бесплатная тренировка с тренером, открыта для любого уровня и без регистрации. Хороший способ начать бегать в компании.', 'Open Run (Almaty Marathon)', 'https://t.me/s/openrunam', 'medium', 'published', 'public'),
  ('seed-011', 'Лекция-практикум «Писать иначе»', 'lecture', array['лекция','письмо','литература']::text[], '2026-10-04T14:00:00+05:00', null, false, (select id from public.venues where name = 'Центр современной культуры «Целинный»'), 'улица Масанчи, 59', 6000, null, false, 'Практикум о необычных подходах к письму и работе с текстом. Для тех, кто пишет сам — хоть роман, хоть блог.', 'Центр современной культуры «Целинный»', 'https://afisha.yandex.kz/almaty/other/places/tsentr-sovremennoi-kultury-tselinnyi/schedule', 'high', 'published', 'public'),
  ('seed-012', 'Концерт «Тринадцать карат»', 'music', array['рэп','концерт','клуб']::text[], '2026-10-04T20:00:00+05:00', null, false, (select id from public.venues where name = 'Motor Club'), 'проспект Назарбаева, 50', 17000, null, false, 'Живой концерт хип-хоп-группы «Тринадцать карат» в клубе. Для поклонников казахстанского рэпа.', null, 'https://sxodim.com/almaty/events/kontserty', 'high', 'published', 'public'),
  ('seed-013', 'Семейный поход «Лунная поляна»', 'hike', array['поход','семья','дети']::text[], '2026-10-04T09:00:00+05:00', null, false, (select id from public.venues where name = 'Лунная поляна'), 'урочище Лунная поляна, Заилийский Алатау', 6000, 8000, false, 'Лёгкий поход для детей 8–15 лет с родителями: готовят на костре и заваривают горный чай. Хороший первый поход для ребёнка. Нужны удобная обувь и одежда по погоде.', 'Monte (mnt.kz)', 'https://t.me/s/montealmaty', 'medium', 'published', 'public'),
  ('seed-014', 'Утренний поход к водопаду через Медеу', 'hike', array['поход','медеу','водопад']::text[], '2026-10-05T06:45:00+05:00', null, false, (select id from public.venues where name = 'Медеу'), 'Медеу, сбор группы', 20000, 20000, false, 'Групповой поход к горному водопаду с заходом на Медеу, около 6 часов без сложных подъёмов. Подойдёт новичкам: закрытая обувь, вода и ветровка.', 'Sputnik8', 'https://www.sputnik8.com/ru/almaty/category/gory', 'high', 'published', 'public'),
  ('seed-015', 'Поход к Большому Алматинскому озеру', 'hike', array['поход','бао','озеро']::text[], '2026-10-06T07:00:00+05:00', null, false, (select id from public.venues where name = 'Большое Алматинское озеро'), 'Большое Алматинское озеро', 38800, 48500, false, 'Мини-группа до 10 человек к бирюзовому озеру на высоте 2511 м, около 7 часов. Нужны треккинговые ботинки и тёплая одежда — наверху холодно даже в октябре.', 'Sputnik8', 'https://www.sputnik8.com/ru/almaty/category/gory', 'high', 'published', 'public'),
  ('seed-016', 'Абзал Утешов', 'music', array['поп','эстрада','концерт']::text[], '2026-10-07T20:00:00+05:00', null, false, (select id from public.venues where name = 'Дворец Республики'), 'проспект Достык, 56', 4000, null, false, 'Сольный концерт казахстанского эстрадного артиста Абзала Утешова. В этот день два выступления — дневное и вечернее.', null, 'https://sxodim.com/almaty', 'high', 'published', 'public'),
  ('seed-017', 'Открытая встреча Almaty Toastmasters', 'meetup', array['клуб','английский','новые люди']::text[], '2026-10-07T19:30:00+05:00', '2026-10-07T21:30:00+05:00', false, (select id from public.venues where name = 'КазНАИУ'), 'проспект Абая, 8', null, null, true, 'Клуб публичных выступлений на английском: можно выступить, получить обратную связь или просто прийти посмотреть. Подходит новичкам.', 'Almaty Toastmasters Club', 'https://t.me/s/AlmatyToastmasters', 'medium', 'published', 'public'),
  ('seed-018', 'Квиз на общие темы', 'games', array['квиз','команды','бар']::text[], '2026-10-08T20:00:00+05:00', null, false, (select id from public.venues where name = 'Harat''s Pub (Желтоксан)'), 'улица Желтоксан — уточнить номер дома', 3500, 3500, false, 'Командная викторина на эрудицию и логику в пабе. Собери друзей или приходи один — в команду возьмут.', 'Chill Quiz Almaty', 'https://chillquiz.kz/quizzes', 'medium', 'published', 'public'),
  ('seed-019', 'Юрий Хайленко «Мало бемолей»', 'music', array['джаз','живая музыка','клуб']::text[], '2026-10-09T19:00:00+05:00', null, false, (select id from public.venues where name = 'EverJazz'), 'улица Жандосова, 1/1', 8000, 8000, false, 'Пианист Юрий Хайленко в камерном джаз-клубе. Для тех, кто любит инструментальный джаз и импровизацию.', 'EverJazz', 'https://sxodim.com/almaty/events/kontserty', 'high', 'published', 'public'),
  ('seed-020', 'NAVAI', 'music', array['поп','концерт','гастроли']::text[], '2026-10-10T19:00:00+05:00', null, false, (select id from public.venues where name = 'Дворец спорта им. Балуана Шолака'), 'проспект Абая, 44', 15000, null, false, 'Большой концерт исполнителя Navai во Дворце спорта.', null, 'https://sxodim.com/almaty/events/kontserty', 'high', 'published', 'public'),
  ('seed-021', 'Лекция-практикум «Писать иначе»', 'lecture', array['лекция','письмо','литература']::text[], '2026-10-11T14:00:00+05:00', null, false, (select id from public.venues where name = 'Центр современной культуры «Целинный»'), 'улица Масанчи, 59', 6000, null, false, 'Практикум о необычных подходах к письму и работе с текстом. Для тех, кто пишет сам — хоть роман, хоть блог.', 'Центр современной культуры «Целинный»', 'https://afisha.yandex.kz/almaty/other/places/tsentr-sovremennoi-kultury-tselinnyi/schedule', 'high', 'published', 'public'),
  ('seed-022', '«Брамс. Искусство диалога»', 'music', array['классика','филармония','камерная музыка']::text[], '2026-10-10T18:00:00+05:00', null, false, (select id from public.venues where name = 'Казахская государственная филармония им. Жамбыла'), 'улица Толе би, 21', null, null, false, 'Программа камерной музыки Брамса о диалоге инструментов. Для любителей академической классики.', 'Казахская государственная филармония им. Жамбыла', 'https://afisha.yandex.kz/almaty/concert/places/filarmoniia-im-zhambyla/schedule', 'high', 'published', 'public'),
  ('seed-023', 'Выставка «Жол: духовные поиски в искусстве Центральной Азии»', 'art', array['выставка','современное искусство','галерея']::text[], '2026-10-10T11:00:00+05:00', '2026-10-10T19:00:00+05:00', true, (select id from public.venues where name = 'Aspan Gallery'), 'проспект Аль-Фараби, 140а/3', null, null, true, 'Групповая выставка о том, как художники Центральной Азии переосмысляют суфийские практики языком современного искусства. Спокойная галерея без толп.', 'Aspan Gallery', 'https://aspangallery.com/ru/exhibitions', 'medium', 'published', 'public'),
  ('seed-024', 'Ева Польна — сольный концерт', 'music', array['поп','концерт','сольник']::text[], '2026-10-11T19:00:00+05:00', null, false, (select id from public.venues where name = 'Дворец Республики'), 'проспект Достык, 56', 15000, null, false, 'Сольный концерт Евы Польны: хиты и новые песни.', null, 'https://sxodim.com/almaty/events/kontserty', 'high', 'published', 'public'),
  ('seed-025', 'Выставка «Мүсіндер»: скульптура Казахстана с 1950-х', 'art', array['выставка','скульптура','музей']::text[], '2026-10-15T10:00:00+05:00', '2026-10-15T18:00:00+05:00', true, (select id from public.venues where name = 'Музей искусств им. А. Кастеева'), 'микрорайон Коктем-3, 22/1', 2000, 5000, false, 'Казахстанская скульптура от 1950-х до наших дней в одном зале. Для тех, кто хочет лучше узнать историю местного искусства.', 'Almaty Museum of Arts', 'https://www.almaty.art/what-is-on', 'medium', 'published', 'public'),
  ('seed-026', 'ZVUK Festival: ночь на Зелёном базаре', 'party', array['электроника','вечеринка','диджей']::text[], '2026-10-16T20:00:00+05:00', null, false, (select id from public.venues where name = 'Зелёный базар'), 'проспект Жибек Жолы, 53', null, null, false, 'Главный павильон Зелёного базара на одну ночь превращается в танцпол. Диджеи из Турции, Ирана, Китая и Казахстана.', 'ZVUK', 'https://kz.kursiv.media/2026-09-08/devy-nochnoi-reiv-proidet-na-zelenom-bazare-v-almaty/', 'high', 'published', 'public'),
